import * as THREE from 'three';
export function buildingFeature(a){const g=new THREE.Group();g.position.set(a.x+a.w/2,0,a.z+a.d/2);g.rotation.y=-a.rotation*Math.PI/180;g.userData={kind:'feature',id:a.id};const add=(w,h,d,x,y,z,color)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshStandardMaterial({color,roughness:.85}));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;g.add(m);return m;};
 if(a.type==='stairs'){const n=Math.max(2,Math.ceil(a.h/.18));for(let i=0;i<n;i++)add(a.w,(i+1)*a.h/n,a.d/n,0,(i+1)*a.h/n/2,-a.d/2+(i+.5)*a.d/n,'#bbb7ad');}
 else if(a.type==='ramp'){const shape=new THREE.Shape();shape.moveTo(-a.d/2,0);shape.lineTo(a.d/2,0);shape.lineTo(a.d/2,a.h);shape.closePath();const m=new THREE.Mesh(new THREE.ExtrudeGeometry(shape,{depth:a.w,bevelEnabled:false}),new THREE.MeshStandardMaterial({color:'#b7b4ac'}));m.rotation.y=-Math.PI/2;m.position.z=0;m.position.x=a.w/2;g.add(m);}
 else if(a.type==='parking'){add(a.w,.025,a.d,0,0,0,'#999c9a');for(const x of [-a.w/2+.03,a.w/2-.03])add(.04,.03,a.d,x,.025,0,'#f5f0d8');add(a.w,.03,.04,0,.025,-a.d/2,'#f5f0d8');if(a.drawnVehicle){add(a.w*.68,a.h*.35,a.d*.8,0,a.h*.175,0,'#d2d5d2');add(a.w*.55,a.h*.3,a.d*.45,0,a.h*.5,0,'#809298');}}
 else if(a.type==='lift'){for(const x of [-a.w/2+.07,a.w/2-.07])add(.14,a.h,a.d,x,a.h/2,0,'#b3b9b8');add(a.w,a.h,.14,0,a.h/2,-a.d/2+.07,'#b3b9b8');add(a.w,.08,a.d,0,.04,0,'#797f80');}
 else add(a.w,a.h,a.d,0,a.h/2,0,a.type==='column'?'#b9b4a8':'#a4b3b1');return g;
}
export function featuresSVG(f){return (f.features||[]).map(a=>`<g transform="rotate(${a.rotation} ${a.x+a.w/2} ${a.z+a.d/2})"><rect x="${a.x}" y="${a.z}" width="${a.w}" height="${a.d}" fill="#a8b3ac" fill-opacity=".65" stroke="#53605c" stroke-width=".04"/><text x="${a.x+a.w/2}" y="${a.z+a.d/2}" font-size=".16" text-anchor="middle">${a.type}</text>${a.type==='stairs'?Array.from({length:12},(_,i)=>`<line x1="${a.x}" y1="${a.z+a.d*(i+1)/13}" x2="${a.x+a.w}" y2="${a.z+a.d*(i+1)/13}" stroke="#53605c" stroke-width=".02"/>`).join(''):''}</g>`).join('');}
